# Optimal 2x2x2 solver using the Homework 1 corner order and moves.
# IDA search stays on the target. The static tables describe the two
# coordinates separately and provide reverse moves within four turns.
    .text
    .globl rubik_solve_asm
    .type rubik_solve_asm, @function
    .align 2
rubik_solve_asm:
    addi sp, sp, -64
    sw ra, 60(sp)
    sw s0, 56(sp)
    sw s1, 52(sp)
    sw s2, 48(sp)
    sw s3, 44(sp)
    sw s4, 40(sp)
    sw s5, 36(sp)
    sw s6, 32(sp)
    sw s7, 28(sp)
    sw s8, 24(sp)
    mv s4, a1
    mv s5, a2
    beqz a0, .Linvalid
    mv t2, a0
    li t0, 7
    li t1, 127
    li s6, 0

    # Rank the permutation and check that every corner occurs once.
.Lrank_corner:
    lbu t3, 0(t2)
    addi t3, t3, -49
    li t4, 7
    bgeu t3, t4, .Linvalid
    li t4, 1
    sll t3, t4, t3
    and t4, t1, t3
    beqz t4, .Linvalid
    addi t4, t3, -1
    and t4, t4, t1
    xor t1, t1, t3

    # Each radix is at most seven. Multiply by repeated addition.
    mv t5, zero
    mv t6, t0
.Lrank_multiply:
    add t5, t5, s6
    addi t6, t6, -1
    bnez t6, .Lrank_multiply
    mv s6, t5
.Lrank_count:
    beqz t4, .Lrank_advance
    addi t3, t4, -1
    and t4, t4, t3
    addi s6, s6, 1
    j .Lrank_count
.Lrank_advance:
    addi t2, t2, 1
    addi t0, t0, -1
    bnez t0, .Lrank_corner

    # The first six orientations form a base-three rank.
    li t0, 7
    li t1, 0
    li s7, 0
.Lrank_twist:
    lbu t3, 0(t2)
    addi t3, t3, -49
    li t4, 3
    bgeu t3, t4, .Linvalid
    add t1, t1, t3
    bltu t1, t4, .Ltwist_add_rank
    addi t1, t1, -3
.Ltwist_add_rank:
    li t4, 1
    beq t0, t4, .Ltwist_advance
    slli t4, s7, 1
    add s7, s7, t4
    add s7, s7, t3
.Ltwist_advance:
    addi t2, t2, 1
    addi t0, t0, -1
    bnez t0, .Lrank_twist
    bnez t1, .Linvalid
    lbu t0, 0(t2)
    bnez t0, .Linvalid

    # Encode the two coordinates as row offsets in halfword units.
    slli t0, s6, 3
    slli s6, s6, 1
    add s6, s6, t0
    slli t0, s7, 3
    slli s7, s7, 1
    add s7, s7, t0
    la s0, .Lperm_rows
    la s1, .Ltwist_rows
    la s2, .Lnear_hash
    slli t0, s6, 1
    add t0, s0, t0
    lhu s8, 0(t0)
    slli t0, s7, 1
    add t0, s1, t0
    lhu t0, 0(t0)
    bgeu s8, t0, .Ltry_bound
    mv s8, t0
.Ltry_bound:
    li t0, 11
    bgtu s8, t0, .Linvalid
    mv a0, s6
    mv a1, s7
    mv a2, s8
    li a3, -1
    mv a4, sp
    call .Lsearch
    bnez a0, .Lmeasure_output
    addi s8, s8, 1
    j .Ltry_bound

.Lmeasure_output:
    la s3, .Lmove_names
    li t3, 1
    beqz s8, .Lcheck_capacity
    mv t0, sp
    add t1, sp, s8
    li t3, 0
.Lmeasure_move:
    lbu t2, 0(t0)
    slli t2, t2, 1
    add t2, s3, t2
    lbu t2, 1(t2)
    snez t2, t2
    addi t3, t3, 2
    add t3, t3, t2
    addi t0, t0, 1
    bne t0, t1, .Lmeasure_move
.Lcheck_capacity:
    bltu s5, t3, .Lsmall_buffer
    mv t0, sp
    add t1, sp, s8
    beq t0, t1, .Lterminate_output
.Lwrite_move:
    lbu t2, 0(t0)
    slli t2, t2, 1
    add t2, s3, t2
    lbu t3, 0(t2)
    sb t3, 0(s4)
    addi s4, s4, 1
    lbu t3, 1(t2)
    beqz t3, .Lwrite_separator
    sb t3, 0(s4)
    addi s4, s4, 1
.Lwrite_separator:
    addi t0, t0, 1
    beq t0, t1, .Lterminate_output
    li t3, 32
    sb t3, 0(s4)
    addi s4, s4, 1
    j .Lwrite_move
.Lterminate_output:
    sb zero, 0(s4)
    mv a0, s8
    j .Lreturn
.Lsmall_buffer:
    li a0, -2
    beqz s5, .Lreturn
    sb zero, 0(s4)
    j .Lreturn
.Linvalid:
    li a0, -1
.Lreturn:
    lw ra, 60(sp)
    lw s0, 56(sp)
    lw s1, 52(sp)
    lw s2, 48(sp)
    lw s3, 44(sp)
    lw s4, 40(sp)
    lw s5, 36(sp)
    lw s6, 32(sp)
    lw s7, 28(sp)
    lw s8, 24(sp)
    addi sp, sp, 64
    ret
    .size rubik_solve_asm, .-rubik_solve_asm

# a0/a1 are coordinate row offsets, a2 is the number of turns left,
# a3 is the previous face's byte offset, and a4 is the next path slot.
.Lsearch:
    addi sp, sp, -16
    sw ra, 12(sp)
    sw s11, 8(sp)
    mv s11, sp
.Lsearch_enter:
    or t0, a0, a1
    beqz t0, .Lsearch_leaf_found
    beqz a2, .Lsearch_leaf_miss
    li t0, 4
    beq a2, t0, .Lsearch_try_tail

    # Keep the pending siblings in an explicit depth-first search stack.
    addi sp, sp, -48
    sw s3, 40(sp)
    sw s4, 36(sp)
    sw s5, 32(sp)
    sw s6, 28(sp)
    sw s7, 24(sp)
    sw s8, 20(sp)
    sw s9, 16(sp)
    sw s10, 12(sp)
    slli s3, a0, 1
    add s3, s3, s0
    addi s3, s3, 2
    slli s4, a1, 1
    add s4, s4, s1
    addi s4, s4, 2
    addi s5, a2, -1
    mv s6, a3
    mv s7, a4
    li s8, 0
.Lsearch_face:
    beq s8, s6, .Lsearch_next_face
    mv s9, s8
    addi s10, s8, 6
.Lsearch_move:
    add t0, s3, s9
    lhu a0, 0(t0)
    slli t0, a0, 1
    add t0, s0, t0
    lhu t1, 0(t0)
    bltu s5, t1, .Lsearch_next_move
    add t0, s4, s9
    lhu a1, 0(t0)
    slli t0, a1, 1
    add t0, s1, t0
    lhu t1, 0(t0)
    bltu s5, t1, .Lsearch_next_move

    mv a2, s5
    mv a3, s8
    addi a4, s7, 1
    j .Lsearch_enter
.Lsearch_next_move:
    addi s9, s9, 2
    bne s9, s10, .Lsearch_move
.Lsearch_next_face:
    addi s8, s8, 6
    li t0, 18
    bne s8, t0, .Lsearch_face
    li a0, 0
    j .Lsearch_return
.Lsearch_save_move:
    srli t0, s9, 1
    sb t0, 0(s7)
.Lsearch_return:
    lw s3, 40(sp)
    lw s4, 36(sp)
    lw s5, 32(sp)
    lw s6, 28(sp)
    lw s7, 24(sp)
    lw s8, 20(sp)
    lw s9, 16(sp)
    lw s10, 12(sp)
    addi sp, sp, 48
.Lsearch_resume:
    beq sp, s11, .Lsearch_exit
    bnez a0, .Lsearch_save_move
    j .Lsearch_next_move

.Lsearch_leaf_found:
    li a0, 1
    j .Lsearch_resume
.Lsearch_leaf_miss:
    li a0, 0
    j .Lsearch_resume
.Lsearch_try_tail:
    call .Lnear_tail
    j .Lsearch_resume
.Lsearch_exit:
    lw ra, 12(sp)
    lw s11, 8(sp)
    addi sp, sp, 16
    ret

# The exact four-turn table supplies the remaining moves on a hit.
.Lnear_tail:
    addi sp, sp, -16
    sw ra, 12(sp)
    sw s3, 8(sp)
    sw s4, 4(sp)
    sw s5, 0(sp)
    mv s3, a0
    mv s4, a1
    mv s5, a4
.Ltail_lookup:
    mv a0, s3
    mv a1, s4
    call .Lnear_move
    beqz a0, .Ltail_return
    addi a0, a0, -1
    sb a0, 0(s5)
    addi s5, s5, 1
    slli t0, a0, 1
    addi t0, t0, 2
    slli t1, s3, 1
    add t1, s0, t1
    add t1, t1, t0
    lhu s3, 0(t1)
    slli t1, s4, 1
    add t1, s1, t1
    add t1, t1, t0
    lhu s4, 0(t1)
    or t0, s3, s4
    bnez t0, .Ltail_lookup
    li a0, 1
.Ltail_return:
    lw ra, 12(sp)
    lw s3, 8(sp)
    lw s4, 4(sp)
    lw s5, 0(sp)
    addi sp, sp, 16
    ret

# A zero slot is empty. Other slots pack the key and the reverse move.
.Lnear_move:
    slli a0, a0, 11
    srli a1, a1, 1
    or a0, a0, a1
    srli t0, a0, 16
    xor t0, t0, a0
    slli t1, t0, 11
    add t0, t0, t1
    srli t1, t0, 16
    xor t0, t0, t1
    slli t1, t0, 4
    add t0, t0, t1
    srli t1, t0, 15
    xor t0, t0, t1
    slli t0, t0, 20
    srli t0, t0, 20
    slli t1, t0, 1
    add t0, t0, t1
    srli t0, t0, 2
    slli t0, t0, 2
    add t0, s2, t0
    li t1, 12288
    add t1, s2, t1
.Lnear_probe:
    lw t2, 0(t0)
    beqz t2, .Lnear_miss
    srli t3, t2, 4
    beq t3, a0, .Lnear_match
    addi t0, t0, 4
    bne t0, t1, .Lnear_probe
    mv t0, s2
    j .Lnear_probe
.Lnear_match:
    andi a0, t2, 15
    ret
.Lnear_miss:
    li a0, 0
    ret

    .section .rodata
.Lmove_names:
